// SECURITY: Validate request
const chatId = $json.body?.chat_id;
const triggerSource = $json.body?.trigger_source;

// 1. Validate chat_id format
if (!chatId || !/^-?\d{7,13}$/.test(String(chatId))) {
  throw new Error('Invalid chat_id format');
}

// 2. Check whitelist (from environment or Google Sheets)
const allowedChatIds = ($env.ALLOWED_CHAT_IDS || '7984101063').split(',');
if (!allowedChatIds.includes(String(chatId))) {
  throw new Error(`Unauthorized chat_id: ${chatId}`);
}

// 3. Rate limiting check
const rateKey = `rate_${chatId}`;
const lastRun = parseInt($vars[rateKey] || '0');
const now = Date.now();
const minInterval = 5 * 60 * 1000; // 5 minutes

if (now - lastRun < minInterval && triggerSource !== 'schedule') {
  const waitTime = Math.ceil((minInterval - (now - lastRun)) / 1000 / 60);
  throw new Error(`Rate limit: wait ${waitTime} minutes`);
}

// Update rate limit
$vars[rateKey] = String(now);

// Pass validated data
return [{
  json: {
    chatId: parseInt(chatId),
    triggerSource: triggerSource || 'unknown',
    timestamp: new Date().toISOString(),
    validated: true
  }
}];

// Обрабатываем результаты Авито с санитизацией
const items = $input.all();
const results = [];

// Helper: sanitize text
const sanitize = (text, maxLength = 200) => {
  if (!text) return '';
  return String(text)
    .replace(/[<>]/g, '')  // Remove HTML
    .replace(/[*_`\[\]]/g, '\\$&')  // Escape Markdown
    .slice(0, maxLength)
    .trim();
};

for (const item of items) {
  const data = item.json;
  if (!data || !data.url) continue;

  // Validate URL domain
  try {
    const url = new URL(data.url);
    if (!url.hostname.endsWith('avito.ru')) {
      console.warn('Suspicious URL:', data.url);
      continue;
    }
  } catch (e) {
    continue;
  }

  results.push({
    json: {
      id: data.url,
      title: sanitize(data.title || 'Квартира', 150),
      price: sanitize(String(data.price || data.priceNum || 'Цена не указана'), 50),
      address: sanitize(data.address || data.location || 'Адрес не указан', 200),
      url: data.url,
      image: data.image || data.imageUrl || data.images?.[0] || null,
      source: 'Авито',
      city: 'Благовещенск',
      timestamp: new Date().toISOString()
    }
  });
}

return results.length > 0 ? results : [{ json: { empty: true } }];

// Обрабатываем результаты ЦИАН с санитизацией
const items = $input.all();
const results = [];

// Helper: sanitize text
const sanitize = (text, maxLength = 200) => {
  if (!text) return '';
  return String(text)
    .replace(/[<>]/g, '')
    .replace(/[*_`\[\]]/g, '\\$&')
    .slice(0, maxLength)
    .trim();
};

for (const item of items) {
  const data = item.json;
  if (!data) continue;

  const cianId = data.cianId || data.id;
  const url = data.siteUrl || data.url || (cianId ? `https://www.cian.ru/rent/flat/${cianId}/` : null);

  if (!url) continue;

  // Validate URL domain
  try {
    const urlObj = new URL(url);
    if (!urlObj.hostname.endsWith('cian.ru')) {
      console.warn('Suspicious URL:', url);
      continue;
    }
  } catch (e) {
    continue;
  }

  const address = data.formattedAddress || data.address || data.geo?.address || 'Адрес не указан';
  const price = data.formattedFullPrice || data.price || data.priceValue || 'Цена не указана';
  const image = data.mainImage?.full || data.image || data.photo || (data.photos && data.photos[0]) || null;

  results.push({
    json: {
      id: url,
      title: sanitize(data.title || 'Квартира', 150),
      price: sanitize(String(price), 50),
      address: sanitize(address, 200),
      url: url,
      image: image,
      source: 'ЦИАН',
      city: 'Благовещенск',
      timestamp: new Date().toISOString()
    }
  });
}

return results.length > 0 ? results : [{ json: { empty: true } }];

// Финальная обработка и дедупликация
const items = $input.all();
const seen = new Set();
const results = [];

for (const item of items) {
  const data = item.json;

  // Пропускаем пустые
  if (data.empty) continue;

  // Проверяем обязательные поля
  if (!data.url && !data.id) continue;

  // Дедупликация по URL
  const key = data.id || data.url;
  if (seen.has(key)) continue;
  seen.add(key);

  // Проверка на наличие изображения (фильтр)
  if (!data.image) continue;

  results.push({
    json: {
      id: data.id || data.url,
      title: data.title || 'Объявление',
      price: data.price || 'Цена не указана',
      address: data.address || 'Адрес не указан',
      url: data.url,
      image: data.image,
      source: data.source || 'Неизвестный источник',
      city: data.city || 'Благовещенск',
      timestamp: data.timestamp || new Date().toISOString()
    }
  });
}

console.log(`Найдено уникальных объявлений: ${results.length}`);
return results.length > 0 ? results : [{ json: { empty: true } }];

